rules:
@media (pointer: coarse) {
  .mouse-stalker, .sticker-cursor-preview { display: none; }
}

@keyframes projectsZoomIn { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}

@keyframes projectsImageZoomIn { 
  0% { opacity: 0; transform-origin: 0px 100%; transform: translate(-18vw, 18vh) scale(0.36); }
  100% { opacity: 1; transform-origin: 50% center; transform: translate(0px, 0px) scale(1); }
}

@keyframes projectsGalleryLoop { 
  0% { transform: translate(0px, 0px); }
  100% { transform: translate(-50%); }
}

@media (max-width: 960px) {
  .projects-gridzoom { gap: clamp(12px, 2vh, 22px); }
  .projects-zoom { padding-bottom: var(--ui-gutter-y); grid-template-rows: minmax(0px, 54svh) auto; grid-template-columns: 1fr; align-items: end; gap: 18px; }
  .projects-zoom__image, .projects-zoom__content { grid-area: auto / 1; }
  .projects-zoom__image { justify-self: center; width: min(100%, 86.4svh); max-height: 54svh; margin-top: 44px; }
  .projects-zoom__image img { height: 100%; }
  .projects-zoom__content { max-width: 640px; }
  .projects-zoom__link { min-height: 38px; margin-top: 18px; }
}

@media (max-width: 620px) {
  .page-shell__header, .projects-gridzoom__header { padding-right: 0px; }
  .page-shell__header span:last-child, .projects-gridzoom__header span:last-child { display: none; }
  .about-language-toggle { justify-self: start; }
  .projects-gridzoom { --projects-grid-padding-x: 18px; padding: 18px; }
  .home-meta { grid-template-columns: 1fr; gap: 10px; width: min(280px, 100%); }
  .home-meta div { border-top: 0px; padding-top: 0px; }
  .home-meta dt { font-size: max(10px, min(2.94vw, 6.5px + 1.029vw)); line-height: 1; }
  .home-meta dd { margin-top: 5px; font-size: max(11px, min(3.235vw, 7.15px + 1.13225vw)); line-height: 1.25; }
  .about-page__content { margin-top: 0px; }
  .about-page__content .page-shell__intro { text-align: left; }
  .contact-page__content { margin-top: 0px; }
  .contact-page__content .page-shell__intro { text-align: center; }
  .about-page__body p { text-align: left; }
  .about-page__body, .contact-page__body { margin-top: clamp(18px, 3.4vh, 26px); }
  .about-page__meta { grid-template-columns: 1fr; }
  .contact-page__links { grid-template-columns: 1fr; gap: 10px; padding-top: clamp(14px, 4vw, 20px); }
  .contact-page__links a { min-height: 30px; font-size: max(18px, min(5.6vw, 16.9px + 1.96vw)); line-height: 1.08; }
  .projects-gridzoom__intro { width: min(max(360px, 234px + 29.6471vw), 100%); margin-top: clamp(56px, 9vh, 76px); }
  .projects-gridzoom__intro h1 { font-size: max(25px, min(7.6vw, 21.45px + 2.66vw)); }
  .projects-gl-caption { min-height: 36px; }
  .projects-gridzoom__item { min-height: auto; }
  .projects-zoom { padding: 18px; display: block; overflow: hidden auto; }
  .projects-zoom__header { top: 18px; left: 18px; }
  .projects-zoom__header .projects-language-toggle button { font-size: max(12px, min(3.529vw, 7.8px + 1.23515vw)); line-height: 1; }
  .projects-zoom__image { aspect-ratio: 4 / 3; width: 100%; max-height: none; margin: 64px 0px 0px; }
  .projects-zoom__image img { height: 100%; }
  .projects-zoom__content { max-width: none; margin: 18px 0px 0px; padding-bottom: 28px; }
  .projects-zoom__content > span { margin-bottom: 12px; }
  .projects-zoom__content h2 { font-size: max(32px, min(9.6vw, 31.2px + 3.36vw)); line-height: 0.96; }
  .projects-zoom__content p { margin-top: 16px; font-size: max(14px, min(4.118vw, 9.1px + 1.4413vw)); line-height: 1.48; }
  .projects-zoom__content dl { grid-template-columns: 1fr; gap: 10px; margin-top: 18px; }
  .projects-zoom__link { min-height: 38px; margin-top: 18px; }
  .projects-zoom__map { display: none; }
}

@media (max-width: 620px) and (max-height: 720px) {
  .projects-zoom__image { aspect-ratio: 16 / 10; }
}
